-- Reviewed batch 14 for 2027 (language schools). Prepared 2026-11-04; apply manually in the Supabase SQL Editor.
-- Sources and limitations: docs/REDESIGN-AND-DATA.md and data/school-reviews.ts.
-- Ten legacy candidates were reviewed; three had no official entity and were removed locally.
-- Controlled sync: explicit inserts for the seven verified entities confirmed absent remotely
-- (remote LanguageSchool had 29 slugs, none of these seven) on 2026-11-04;
-- no DELETE, bulk import, or schema changes.
BEGIN;
DO $$ BEGIN
  IF (SELECT count(*) FROM "LanguageSchool" WHERE slug IN ('sendai-jls', 'hokkaido-ir', 'hiroshima-jls', 'okayama-jls', 'saitama-jls', 'tsukuba-jls', 'kawasaki-jls')) <> 0 THEN
    RAISE EXCEPTION 'One or more reviewed records already exist; no inserts applied';
  END IF;
END $$;
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'sendai-jls', '仙台语言学校', '仙台ランゲージスクール', '宫城县仙台市青叶区一番町1-14-32 Freihait大楼8F', '官网常规留学签课程页未公开可核对的2027费用表；旧的80万日元年费已删除。', '本批未核实。', '本批未核实。', '24个月、21个月、18个月或15个月', '面向海外申请长期留学签课程者；应在各期开课约6个月前按校方期限准备材料。', '本批未核实。', '4月（24个月）/7月（21个月）/10月（18个月）/1月（15个月）。', '已按官网学校名与校址更正；课程页只确认年限、入学期和留学签流程，未将未经公开的费用或东北大学升学承诺写作事实。', 'https://sendai-lang.com/english/japanese/regular/', '["常规留学签课程","四季入学","最大24个月","仙台市青叶区"]'::jsonb, '[{"name":"常规课程（留学签）","description":"以长期留学签学习为目标，按分级测试安排上午或下午课程。"}]'::jsonb, '{"enrollmentFee":"2027费用待校方公布","annualTuition":"2027费用待校方公布","materialsFee":"2027费用待校方公布","totalFirstYear":"2027费用待校方公布"}'::jsonb, '["计划仙台长期日语学习","需要1/4/7/10月入学选择","愿意向校方确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'hokkaido-ir', '北海道日本语学院札幌本校', '北海道日本語学院札幌本校', '北海道札幌市中央区北6条西25丁目1-5', '官网当前首年909,000日元（选考30,000、入学66,000、设施等120,000、授课693,000）；页面未标注为2027费用。', '以官网申请要项与当期通知为准。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '升学课程1年6月、1年9月或2年；一般长课1年', '留学签长期课程须完成12年教育并接受入管材料审查。', '本批未核实。', '留学签课程入学期以当期要项为准。', '已修正旧地址与费用；官网有升学课程和一般课程，但不再声称北海道大学目标班或未经核实的生活成本比例。', 'https://h-nihongo.org/en/course-no-have-visa.html', '["札幌本校","升学与一般长课","EJU/JLPT对策","当前首年费用公开"]'::jsonb, '[{"name":"升学课程","description":"1年6月、1年9月或2年，提供JLPT与EJU对策及升学支持。"},{"name":"一般长课","description":"1年课程，面向日常生活所需日语能力。"}]'::jsonb, '{"enrollmentFee":"入学金66,000日元（另有选考料30,000日元）","annualTuition":"授课费693,000日元","materialsFee":"设施等120,000日元","totalFirstYear":"909,000日元（官网当前表）","otherFees":"第二年依剩余学习期为406,500至813,000日元；2027金额待校方确认"}'::jsonb, '["计划札幌长期日语课程","需要升学或一般日语方向","能以申请时要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'hiroshima-jls', 'HLA日本语学校', 'HLA日本語学校', '广岛县东广岛市西条町御薗宇6428-1（JR西条站乘巴士“上户”下车步行6分、“城信”下车步行3分）', '学校《学生募集要項》公开的现行金额：进学2年课程首年798,400、第二年696,400日元（两年合计1,494,800）；进学1年6月课程首年同为798,400日元。其中选考料22,000日元于出愿时缴纳，在留资格认定证明书下来后缴纳其余776,400日元。要项未标注为2027年度金额。', '以校方当期募集要项与纳付金返還规定为准。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '进学2年课程（4月入学）或进学1年6月课程（10月入学）', '须完成12年以上学校教育或同等课程、年满18岁，并具备150小时以上日语学习经历；2年课程需CEFR A1（JLPT N5相当），1年6月课程需CEFR A2（JLPT N4相当）。选拔为面试与笔试。', '本批未核实。', '4月（2年课程，定员300名）/10月（1年6月课程，定员200名）。', '原名“广岛日本语学院”在官方名录与学校官网上均无法对应，已按实际存在的HLA日本語学校更正；校址、课程与公开纳付金均取自学校官网与日语教育振兴协会登记。', 'https://www.hla201904.com/', '["法务省告示校","东广岛市学园都市","进学2年与1年6月课程","设有学生宿舍"]'::jsonb, '[{"name":"进学2年课程","description":"4月入学，定员300名，面向升入日本大学、大学院或专门学校；入学需CEFR A1（N5相当）。"},{"name":"进学1年6月课程","description":"10月入学，定员200名，入学需CEFR A2（N4相当）日语力。"}]'::jsonb, '{"enrollmentFee":"选考料22,000日元（出愿时）＋入学金77,000日元","annualTuition":"授课费每年610,500日元（1年6月课程尾年305,250日元）","materialsFee":"教材费每年35,500日元；设施费每年25,000日元","totalFirstYear":"798,400日元（含税，现行要项；非2027承诺）","otherFees":"课外活动8,800、保险10,000、健康管理6,600、接送3,000日元（首年）；JLPT及J.TEST报考费按预收款另收"}'::jsonb, '["计划广岛县长期升学课程","具备N5/N4相当日语基础","能以当期要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'okayama-jls', '冈山外语学院', '岡山外語学院', '冈山县冈山市北区舟桥町2-10（冈山站打车约10分；路面电车清辉桥线“东中央町”下车步行5分）', '日语教育振兴协会公开的现行纳付金：进学2年课程合计1,555,000日元（选考20,000、入学金70,000、授课费1,260,000、其他205,000）；进学1年6月课程合计1,196,500日元；进学1年课程合计838,000日元。该表未标注为2027年度金额，2027费用待校方要项确认。', '以校方当期募集要项为准。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '进学2年／1年6月／1年课程', '须完成12年课程以上或同等学力，并具备JLPT N5合格或同等日语能力；选拔为书类审查、本人面试、N5水平日语测试与能力适性测试。', '本批未核实。', '4月（2年课程、1年课程）/10月（1年6月课程）。', '原名“冈山日本语学院”无法对应官方实体，已更正为冈山市实际存在的岡山外語学院；校址、课程与公开纳付金取自学校官网与日语教育振兴协会登记，不再沿用旧的“78万日元/年”与统一出勤率断言。', 'https://okg-jp.com/', '["文部科学省认定日语教育机构","学校法人亚洲之风","三种进学课程","设有学生宿舍"]'::jsonb, '[{"name":"进学2年课程","description":"4月入学，1,600单位时间、80周，面向高等教育升学。"},{"name":"进学1年6月课程","description":"10月入学，1,200单位时间、60周。"},{"name":"进学1年课程","description":"4月入学，800单位时间、40周。"}]'::jsonb, '{"enrollmentFee":"选考料20,000日元＋入学金70,000日元","annualTuition":"2年课程全程授课费1,260,000日元；1年6月课程945,000日元；1年课程630,000日元","materialsFee":"其他（教材、设施等）2年课程205,000日元；1年6月课程161,500日元；1年课程118,000日元","totalFirstYear":"2年课程全程1,555,000日元；1年6月课程1,196,500日元；1年课程838,000日元（现行公开额，非2027承诺）","otherFees":"金额为全程合计而非首年；宿舍约23,833日元/月另计"}'::jsonb, '["计划冈山长期升学课程","具备N5相当日语能力","能以当期要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'saitama-jls', '埼玉日本语学校', '埼玉日本語学校', '埼玉县埼玉市大宫区土手町1-58-1', '学校规则公开年额：入学金70,000、授课费600,000、设施费80,000、保险10,000日元；健康检查费另列。公开规则未标注为2027费用。', '依校方当期要项确认。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '以校方当期课程要项为准', '以升入日本高等教育机构为目的，须完成12年教育或同等学历。', '本批未核实。', '以校方当期要项为准。', '已更正名称、地址与费用构成；不再将东京通勤时间、生活成本或统一N5条件写作事实。', 'https://s-jls.ac.jp/', '["学校法人","大宫区土手町","升学导向","学习与生活支持"]'::jsonb, '[{"name":"升学日语课程","description":"面向大学、大学院或专门学校升学，具体课程年限以校方要项为准。"}]'::jsonb, '{"enrollmentFee":"入学金70,000日元","annualTuition":"授课费600,000日元","materialsFee":"以校方当期通知为准","totalFirstYear":"至少760,000日元，另加健康检查与其他当期项目","otherFees":"设施费80,000、保险10,000日元；2027金额待校方确认"}'::jsonb, '["计划埼玉升学日语课程","希望获得学习与生活咨询","能以申请时要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'tsukuba-jls', '日本筑波国际语学院', '日本つくば国際語学院', '茨城县筑波市松代2-4', '官网当前2年/1年6月课程首年全缴均665,000日元（选考20,000、入学金全缴免除、授课600,000、其他45,000）；分期首年715,000日元。公开页未标为2027费用。', '授课费可半年分纳；首年全缴可免入学金。', '全勤、精勤奖仅是校内奖励；本批未核实通用签证出勤率门槛。', '2年（4月）或1年6月（10月）', '须18岁以上并完成12年教育，具150小时A1相当日语学习经历或JLPT N5相当；原则上毕业后5年内。', '本批未核实。', '4月（2年）/10月（1年6月）。', '已纠正为官网学校全称；学校支持升学但不再捏造“筑波大学目标班”。', 'https://www.tlc.ac.jp/course-international', '["学校法人","筑波市松代","两种升学课程","首年全缴可免入学金"]'::jsonb, '[{"name":"进学2年课程","description":"4月入学、1,520学时，面向日本高等教育机构升学。"},{"name":"进学1年6月课程","description":"10月入学、1,140学时，面向升学准备。"}]'::jsonb, '{"enrollmentFee":"选考料20,000日元；首年全缴时入学金50,000日元免除","annualTuition":"授课费600,000日元","materialsFee":"其他45,000日元，含设施、教材、课外活动、健康检查、签证申请与保险等项目","totalFirstYear":"全缴665,000日元；分期715,000日元","otherFees":"2年课程第二年645,000日元；1年6月课程第二年322,500日元（当前表，非2027承诺）"}'::jsonb, '["计划筑波升学日语课程","具备N5/A1或150小时学习经历","能以申请时要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'kawasaki-jls', '川崎日本语学院', '川崎日本語学院', '神奈川县（法务省告示校名录列为神奈川县；本批未取得可访问的校方页面确认具体校址）', '该校在法务省告示的日语教育机构名录内，但本批未能找到可访问的学校官网或公开费用页；旧的“约88万日元/年”已删除。2027年费用与分纳规则须由校方书面确认。', '待校方公布。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '待校方公布', '待校方公布；申请留学签前应由校方确认当期条件与材料期限。', '本批未核实。', '待校方公布（旧的1/4/7/10月入学未获校方资料证实）', '学校本体以法务省告示的日语教育机构名录为据；因本批未能找到可访问的校方页面，旧的学费、入学期、出勤率与“品川/涩谷10分钟”等表述全部删除，未以推测或中介站数据填充。', '', '["法务省告示的日语教育机构","神奈川县","费用与课程待校方确认"]'::jsonb, '[{"name":"课程构成","description":"该校列入法务省告示名录，但公开渠道未见课程要项；具体课程、年限与入学期须向校方索取当期募集要项。"}]'::jsonb, '{"enrollmentFee":"待校方公布","annualTuition":"待校方公布","materialsFee":"待校方公布","totalFirstYear":"待校方公布","otherFees":"旧数据中的统一年费已删除，不作为2027报价"}'::jsonb, '["希望向校方直接核实资料","能接受费用待确认"]'::jsonb
);
COMMIT;
